from pathlib import Path
import xml.etree.ElementTree as ET
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak

ROOT=Path(__file__).resolve().parents[1];JUNIT=ROOT/'test-results'/'junit.xml';OUT=ROOT/'output'/'pdf'/'SBB-Oxygen-House-Admin-Contact-Cards-Test-Report.pdf'
if not JUNIT.exists():raise SystemExit('Run npm run test:contact-cards:all first.')
rows=[]
for suite in ET.parse(JUNIT).getroot().findall('testsuite'):
 for case in suite.findall('testcase'):
  name=case.get('name','')
  if 'CARDS-MATRIX-' not in name:continue
  fail=case.find('failure');result='FAILED'if fail is not None else('SKIPPED'if case.find('skipped')is not None else'PASSED')
  rows.append([name.split('>')[-1].strip(),suite.get('hostname','Unknown'),result,f"{float(case.get('time',0)):.1f}s",'Verified'if result=='PASSED'else'Investigate attached Playwright evidence.'])
if len(rows)!=24:raise SystemExit(f'Expected 24 Contact Cards matrix results, found {len(rows)}. Run npm run test:contact-cards:all.')
p=sum(r[2]=='PASSED'for r in rows);f=sum(r[2]=='FAILED'for r in rows);sk=sum(r[2]=='SKIPPED'for r in rows)
OUT.parent.mkdir(parents=True,exist_ok=True);styles=getSampleStyleSheet();navy=colors.HexColor('#102331');teal=colors.HexColor('#0B6980');line=colors.HexColor('#B9C9D1');green=colors.HexColor('#DDF4E6');red=colors.HexColor('#FADADA');amber=colors.HexColor('#FFF0C2')
title=ParagraphStyle('Title',parent=styles['Title'],fontSize=19,leading=23,textColor=navy,spaceAfter=3*mm);h=ParagraphStyle('H',parent=styles['Heading1'],fontSize=13,leading=16,textColor=teal,spaceBefore=3*mm,spaceAfter=2*mm);body=ParagraphStyle('Body',parent=styles['BodyText'],fontSize=8.5,leading=12,textColor=navy);small=ParagraphStyle('Small',parent=body,fontSize=7,leading=9);tiny=ParagraphStyle('Tiny',parent=body,fontSize=5.7,leading=6.6)
def footer(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(line);canvas.line(14*mm,12*mm,196*mm,12*mm);canvas.setFillColor(colors.HexColor('#607783'));canvas.setFont('Helvetica',6.5);canvas.drawString(14*mm,8*mm,'SBB Oxygen House - Admin Contact Cards Test Report');canvas.drawRightString(196*mm,8*mm,f'Page {doc.page}');canvas.restoreState()
doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=14*mm,rightMargin=14*mm,topMargin=14*mm,bottomMargin=17*mm,title='Admin Contact Cards Test Report',author='Calibur Automation')
story=[Paragraph('SBB OXYGEN HOUSE',ParagraphStyle('Brand',parent=small,textColor=teal,fontSize=10,leading=12)),Paragraph('ADMIN CONTACT CARDS TEST REPORT',title),Paragraph('Functional, validation, test-data lifecycle, UI, nonfunctional and browser compatibility evidence',body),Spacer(1,5*mm)]
summary=Table([['Target','Matrix','Passed','Failed','Skipped'],['/admin/contact-cards',len(rows),p,f,sk]],colWidths=[72*mm,27*mm,27*mm,27*mm,27*mm]);summary.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ALIGN',(1,0),(-1,-1),'CENTER'),('GRID',(0,0),(-1,-1),.4,line),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story +=[summary,Spacer(1,5*mm),Paragraph('Executive result',h),Paragraph(f'The compatibility matrix completed with <b>{p} passed, {f} failed and {sk} skipped</b>. The focused Chrome suite completed with <b>10 passed and 3 failed</b>. The separate generated-data lifecycle passed and restored all original Main Branch values.',body),Paragraph('Confirmed validation findings',h)]
findings=[['Severity','Validation','Observed behavior and correction'],['High','Mobile required','Blank mobile data passes native form validity. Mark the field required and add server-side required validation.'],['High','Email required','Malformed email is rejected, but blank email passes validity. Add required validation in UI and API.'],['High','Address required','Blank address data passes validity. Add required validation in UI and API.']]
ft=Table([[Paragraph(str(c),small)for c in row]for row in findings],colWidths=[24*mm,41*mm,115*mm]);ft.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('TEXTCOLOR',(0,0),(-1,0),colors.white),('BACKGROUND',(0,1),(0,-1),amber),('GRID',(0,0),(-1,-1),.4,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),5)]));story +=[ft,Spacer(1,4*mm),Paragraph('Generated test-data lifecycle',h),Paragraph('The lifecycle creates unique temporary mobile, email and address values for Main Branch, saves them, reloads the page, and verifies persistence for all three fields. It then restores the exact original values, saves again, reloads and verifies restoration. A guarded finally block performs restoration if any intermediate assertion fails.',body),Paragraph('Branch data covered',h),Paragraph('Main Branch, Wallampitiya Branch, Wattala Branch and Panchikawatte Branch are checked for visible headings and populated Mobile, Email and Address fields.',body)]
story +=[PageBreak(),Paragraph('Detailed coverage',title)]
coverage=[('Functional identity','Authenticated route, heading, description, four branch cards and Save Changes control.'),('Existing values','All 12 branch fields are populated; email values follow a valid address format.'),('Format validation','Malformed email test data is rejected without saving.'),('Required validation','Blank mobile, email and address cases are asserted independently; all three currently fail.'),('Generated test data','Unique mobile, email and address values are saved, persisted and fully restored.'),('Keyboard and controls','Save Changes can receive keyboard focus; form controls meet usable sizing.'),('UI and responsive','Card layout, field sizing and document-width overflow.'),('Accessibility','Axe WCAG scan with zero critical violations in tested states.'),('Performance','Authenticated page readiness under 10 seconds.'),('Security','HTTPS, exact authenticated route and no login redirect.'),('Runtime quality','Uncaught JavaScript errors and HTTP 5xx responses.'),('Compatibility','Chrome, Edge, Firefox and Safari-compatible web/mobile: 8 profiles x 3 checks = 24.')]
ct=Table([['Testing area','What was verified']]+[[Paragraph(a,small),Paragraph(b,small)]for a,b in coverage],colWidths=[43*mm,137*mm],repeatRows=1);ct.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),4)]));story +=[ct,Spacer(1,4*mm),Paragraph('Browser interpretation',h),Paragraph('Chrome and Edge profiles use installed vendor browsers. Firefox uses Playwright Firefox. Safari-compatible profiles use Playwright WebKit on Windows and represent engine-level compatibility, not certification on physical Apple Safari.',body),Paragraph('Conclusion',h),Paragraph('Contact Cards rendering, populated data, save persistence, restoration, email format validation, accessibility, responsive layout, performance, HTTPS and runtime quality are operational. Release acceptance should remain conditional on adding required validation for Mobile, Email and Address.',body)]
story +=[PageBreak(),Paragraph('Compatibility matrix results',title),Paragraph('Each row is from the latest JUnit execution generated by npm run test:contact-cards:all.',body),Spacer(1,3*mm)]
data=[['Test case','Profile','Result','Time','Finding']]+[[Paragraph(r[0],tiny),Paragraph(r[1],tiny),Paragraph(r[2],tiny),Paragraph(r[3],tiny),Paragraph(r[4],tiny)]for r in rows];dt=Table(data,colWidths=[77*mm,34*mm,20*mm,15*mm,34*mm],repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),3)]
for i,r in enumerate(rows,1):cmd.append(('BACKGROUND',(2,i),(2,i),green if r[2]=='PASSED'else red if r[2]=='FAILED'else amber))
dt.setStyle(TableStyle(cmd));story.append(dt);doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
